def dedupe(items: list) -> list:
    """
    Return a new list with duplicates removed, preserving the first occurrence
    of each item and the original order. Items may be of any type, including
    unhashable types like lists and dicts, and may contain self-referential
    structures. A custom equality comparison with recursion guard is used
    to avoid RecursionError.
    """
    def eq(a, b, seen=None):
        """
        Recursively compare two objects for equality, handling self-referential
        structures by keeping a set of already compared id pairs.
        """
        if seen is None:
            seen = set()
        pair = (id(a), id(b))
        if pair in seen:
            # Already comparing these objects; treat as equal to break recursion
            return True
        seen.add(pair)

        # Direct identity check
        if a is b:
            return True

        # Compare types
        if type(a) != type(b):
            return False

        # Handle built-in containers
        if isinstance(a, (list, tuple)):
            if len(a) != len(b):
                return False
            return all(eq(x, y, seen) for x, y in zip(a, b))

        if isinstance(a, dict):
            if a.keys() != b.keys():
                return False
            return all(eq(a[k], b[k], seen) for k in a)

        if isinstance(a, set):
            # Sets are unordered; compare by elements
            if len(a) != len(b):
                return False
            # Convert to list for deterministic comparison
            return all(any(eq(x, y, seen) for y in b) for x in a)

        # Fallback to standard equality
        try:
            return a == b
        except Exception:
            return False

    result = []
    for item in items:
        if not any(eq(item, existing) for existing in result):
            result.append(item)
    return result

